{"code": "import impl
import pytest


class TestNormalPath:
    """Test normal success and failure paths."""

    def test_matching_allow_returns_allow(self):
        request = {
            'subject': 'alice',
            'roles': ['user'],
            'action': 's3:GetObject',
            'resource': 'bucket/key'
        }
        policies = [
            {
                'effect': 'ALLOW',
                'principal': 'user:alice',
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
        ]
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_matching_deny_returns_deny(self):
        request = {
            'subject': 'alice',
            'roles': [],
            'action': 's3:GetObject',
            'resource': 'bucket/key'
        }
        policies = [
            {
                'effect': 'DENY',
                'principal': 'user:alice',
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
        ]
        assert impl.authorize(request, policies) == 'DENY'

    def test_no_matching_policies_defaults_to_deny(self):
        request = {
            'subject': 'alice',
            'roles': [],
            'action': 's3:GetObject',
            'resource': 'bucket/key'
        }
        policies = []
        assert impl.authorize(request, policies) == 'DENY'


class TestDenyOverrides:
    """Test deny-overrides rule-combining (XACML 3.0)."""

    def test_deny_overrides_allow_regardless_of_order(self):
        """DENY wins even when ALLOW appears first."""
        request = {
            'subject': 'alice',
            'roles': [],
            'action': 's3:GetObject',
            'resource': 'bucket/key'
        }
        policies = [
            {
                'effect': 'ALLOW',
                'principal': 'user:alice',
                'action': '*',
                'resource': '*'
            },
            {
                'effect': 'DENY',
                'principal': 'user:alice',
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
        ]
        assert impl.authorize(request, policies) == 'DENY'

    def test_role_deny_overrides_user_allow(self):
        """Role-based DENY overrides user-specific ALLOW."""
        request = {
            'subject': 'alice',
            'roles': ['contractor'],
            'action': 'docs:Read',
            'resource': 'docs/reports/Q1'
        }
        policies = [
            {
                'effect': 'ALLOW',
                'principal': 'user:alice',
                'action': '*',
                'resource': 'docs/reports/*'
            },
            {
                'effect': 'DENY',
                'principal': 'role:contractor',
                'action': '*',
                'resource': 'docs/reports/*'
            }
        ]
        assert impl.authorize(request, policies) == 'DENY'


class TestPatternMatching:
    """Test pattern matching for actions and resources."""

    def test_wildcard_only_matches_everything(self):
        """* alone matches any action or resource."""
        request = {
            'subject': 'alice',
            'roles': [],
            'action': 'anything:Action',
            'resource': 'any/resource/path'
        }
        policies = [
            {
                'effect': 'ALLOW',
                'principal': 'user:alice',
                'action': '*',
                'resource': '*'
            }
        ]
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_trailing_asterisk_prefix_match(self):
        """Trailing * on action and resource is prefix match."""
        request = {
            'subject': 'alice',
            'roles': [],
            'action': 's3:GetObject',
            'resource': 'docs/reports/Q1'
        }
        policies = [
            {
                'effect': 'ALLOW',
                'principal': 'user:alice',
                'action': 's3:Get*',
                'resource': 'docs/reports/*'
            }
        ]
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_trailing_asterisk_does_not_cross_boundary(self):
        """docs/reports/* does not match docs/reportsQ1."""
        request = {
            'subject': 'alice',
            'roles': [],
            'action': 's3:GetObject',
            'resource': 'docs/reportsQ1'
        }
        policies = [
            {
                'effect': 'ALLOW',
                'principal': 'user:alice',
                'action': 's3:GetObject',
                'resource': 'docs/reports/*'
            }
        ]
        assert impl.authorize(request, policies) == 'DENY'

    def test_non_final_asterisk_is_literal(self):
        """s3:*Object is literal, not a pattern."""
        request = {
            'subject': 'alice',
            'roles': [],
            'action': 's3:GetObject',
            'resource': 'bucket/key'
        }
        policies = [
            {
                'effect': 'ALLOW',
                'principal': 'user:alice',
                'action': 's3:*Object',
                'resource': 'bucket/key'
            }
        ]
        assert impl.authorize(request, policies) == 'DENY'

    def test_pattern_matching_is_case_sensitive(self):
        """Pattern matching is case-sensitive."""
        request = {
            'subject': 'alice',
            'roles': [],
            'action': 'S3:GetObject',
            'resource': 'bucket/key'
        }
        policies = [
            {
                'effect': 'ALLOW',
                'principal': 'user:alice',
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
        ]
        assert impl.authorize(request, policies) == 'DENY'


class TestPrincipalMatching:
    """Test principal matching rules."""

    def test_principal_wildcard_matches_any(self):
        """'*' principal matches any subject and roles."""
        request = {
            'subject': 'alice',
            'roles': ['user'],
            'action': 's3:GetObject',
            'resource': 'bucket/key'
        }
        policies = [
            {
                'effect': 'ALLOW',
                'principal': '*',
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
        ]
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_principal_user_matching(self):
        """user:{subject} matches exactly; user:al* is literal, not a pattern."""
        request = {
            'subject': 'alice',
            'roles': [],
            'action': 's3:GetObject',
            'resource': 'bucket/key'
        }
        # Exact match should work
        policies_exact = [
            {
                'effect': 'ALLOW',
                'principal': 'user:alice',
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
        ]
        assert impl.authorize(request, policies_exact) == 'ALLOW'

        # Wildcard-like principal is literal, not a pattern
        policies_pattern = [
            {
                'effect': 'ALLOW',
                'principal': 'user:al*',
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
        ]
        assert impl.authorize(request, policies_pattern) == 'DENY'

    def test_principal_role_matching(self):
        """role:{rolename} matches if rolename is in request roles."""
        # With admin role
        request_with_admin = {
            'subject': 'alice',
            'roles': ['admin', 'user'],
            'action': 's3:GetObject',
            'resource': 'bucket/key'
        }
        policies = [
            {
                'effect': 'ALLOW',
                'principal': 'role:admin',
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
        ]
        assert impl.authorize(request_with_admin, policies) == 'ALLOW'

        # Without admin role should deny
        request_without_admin = {
            'subject': 'alice',
            'roles': ['user'],
            'action': 's3:GetObject',
            'resource': 'bucket/key'
        }
        assert impl.authorize(request_without_admin, policies) == 'DENY'


class TestValidation:
    """Test validation of requests and policies."""

    def test_request_missing_required_field(self):
        """Raise ValueError if request missing required field."""
        for field in ['subject', 'roles', 'action', 'resource']:
            request = {
                'subject': 'alice',
                'roles': [],
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
            del request[field]
            with pytest.raises(ValueError, match=f"Request missing required field: {field}"):
                impl.authorize(request, [])

    def test_request_roles_not_list(self):
        """Raise ValueError if request 'roles' is not a list."""
        request = {
            'subject': 'alice',
            'roles': 'admin',
            'action': 's3:GetObject',
            'resource': 'bucket/key'
        }
        with pytest.raises(ValueError, match="Request 'roles' must be a list"):
            impl.authorize(request, [])

    def test_policy_missing_required_field(self):
        """Raise ValueError if policy missing required field."""
        for field in ['effect', 'principal', 'action', 'resource']:
            request = {
                'subject': 'alice',
                'roles': [],
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
            policy = {
                'effect': 'ALLOW',
                'principal': 'user:alice',
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
            del policy[field]
            with pytest.raises(ValueError, match=f"Policy missing required field: {field}"):
                impl.authorize(request, [policy])

    def test_invalid_effect_rejects_typos(self):
        """Raise ValueError for typos like 'Allow' or 'PERMIT'."""
        request = {
            'subject': 'alice',
            'roles': [],
            'action': 's3:GetObject',
            'resource': 'bucket/key'
        }
        for invalid_effect in ['Allow', 'PERMIT']:
            policy = {
                'effect': invalid_effect,
                'principal': 'user:alice',
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
            with pytest.raises(ValueError, match=f"Invalid policy effect: {invalid_effect}"):
                impl.authorize(request, [policy])

    def test_validation_before_decision(self):
        """Validation of all policies happens before any decision logic."""
        request = {
            'subject': 'alice',
            'roles': [],
            'action': 's3:GetObject',
            'resource': 'bucket/key'
        }
        policies = [
            {
                'effect': 'ALLOW',
                'principal': 'user:alice',
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            },
            {
                'effect': 'INVALID',
                'principal': 'user:bob',
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
        ]
        with pytest.raises(ValueError, match="Invalid policy effect: INVALID"):
            impl.authorize(request, policies)

    def test_immutability(self):
        """authorize() does not mutate the request or policies."""
        request = {
            'subject': 'alice',
            'roles': ['user'],
            'action': 's3:GetObject',
            'resource': 'bucket/key'
        }
        policies = [
            {
                'effect': 'ALLOW',
                'principal': 'user:alice',
                'action': 's3:GetObject',
                'resource': 'bucket/key'
            }
        ]
        original_request = dict(request)
        original_policies = [dict(p) for p in policies]
        impl.authorize(request, policies)
        assert request == original_request
        assert policies == original_policies"}
